// OER WEEKLY SUMMARY, stage 3: the week's videos from its cards + voice.
//
//   node recap/build/video.mjs 2026-W47              wide, tall, thumbnail, description
//   node recap/build/video.mjs 2026-W47 --only wide
//
// Needs recap/out/<week>.wav (+ .timing.json) and <week>-short.wav from
// voice.mjs. Opens /recap/render/ in headless Chromium (Playwright; set
// RECAP_BROWSER=msedge to use an installed Edge), takes one picture per
// spoken line, and joins them with ffmpeg so each card shows from the
// moment its line is spoken. A low hum generated by ffmpeg sits under
// the voice (recap/assets/CREDITS.md). Writes into recap/out/:
//   OER-WEEKLY-SUMMARY-<week>.mp4        1920x1080
//   OER-WEEKLY-SUMMARY-<week>-SHORT.mp4  1080x1920, under 60 s
//   OER-WEEKLY-SUMMARY-<week>-THUMB.png  1280x720
//   OER-WEEKLY-SUMMARY-<week>-YOUTUBE.txt title, description, tags
// Exit code 2 = something is missing or wrong; nothing to publish.
import fs from "node:fs";
import path from "node:path";
import http from "node:http";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const RECAP = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const SITE = path.join(RECAP, "..");
const OUT = path.join(RECAP, "out");
const args = process.argv.slice(2);
const week = String(args[0] || "").toUpperCase();
const only = args.includes("--only") ? args[args.indexOf("--only") + 1] : "";
const FPS = 30;
export const SHORT_MAX_SECONDS = 59;

export const fileBase = (w) => "OER-WEEKLY-SUMMARY-" + w;

// Frames: one per spoken line. A line's card shows from its start to the
// next line's start; the first card from 0, the last to the end.
export function frameTimes(timing) {
  const list = [];
  timing.paragraphs.forEach((p, s) => p.sentences.forEach((x, k) => list.push({ scene: s, step: k + 1, start: x.start })));
  list.forEach((f, i) => {
    const from = i === 0 ? 0 : f.start;
    const to = i + 1 < list.length ? list[i + 1].start : timing.duration;
    f.duration = Math.max(1 / FPS, to - from);
  });
  return list;
}

// ffmpeg concat list (the last picture is listed twice, as ffmpeg wants).
export function concatList(frames, dir) {
  const lines = [];
  frames.forEach((f, i) => { lines.push("file '" + path.join(dir, name(i)).replace(/\\/g, "/") + "'", "duration " + f.duration.toFixed(3)); });
  if (frames.length) lines.push("file '" + path.join(dir, name(frames.length - 1)).replace(/\\/g, "/") + "'");
  return lines.join("\n") + "\n";
}
const name = (i) => "f" + String(i).padStart(4, "0") + ".png";

function ffmpegPath() {
  if (process.env.FFMPEG) return process.env.FFMPEG;
  try { return require("ffmpeg-static"); } catch (e) { return "ffmpeg"; }
}

function run(bin, a) {
  const r = spawnSync(bin, a, { stdio: ["ignore", "ignore", "pipe"], maxBuffer: 64 * 1024 * 1024 });
  if (r.status !== 0) throw new Error(path.basename(bin) + " failed: " + String(r.stderr || "").split("\n").slice(-6).join(" | "));
}

// Static server over the website folder, for the render page.
function serve() {
  const types = { ".html": "text/html", ".js": "text/javascript", ".json": "application/json", ".png": "image/png", ".css": "text/css", ".svg": "image/svg+xml" };
  const srv = http.createServer((req, res) => {
    const u = decodeURIComponent(new URL(req.url, "http://x").pathname);
    let f = path.normalize(path.join(SITE, u));
    if (!f.startsWith(SITE)) { res.writeHead(403); return res.end(); }
    if (fs.existsSync(f) && fs.statSync(f).isDirectory()) f = path.join(f, "index.html");
    if (!fs.existsSync(f)) { res.writeHead(404); return res.end(); }
    res.writeHead(200, { "content-type": types[path.extname(f)] || "application/octet-stream" });
    fs.createReadStream(f).pipe(res);
  });
  return new Promise((ok) => srv.listen(0, "127.0.0.1", () => ok(srv)));
}

async function cards(browser, base, fmt, size, frames, dir) {
  fs.rmSync(dir, { recursive: true, force: true });
  fs.mkdirSync(dir, { recursive: true });
  const page = await browser.newPage({ viewport: size, deviceScaleFactor: 1 });
  await page.goto(base + "/recap/render/?week=" + week + "&fmt=" + fmt, { waitUntil: "load" });
  await page.waitForFunction(() => window.recapReady || window.recapError, null, { timeout: 30000 });
  const err = await page.evaluate(() => window.recapError || "");
  if (err) throw new Error("render page: " + err);
  for (let i = 0; i < frames.length; i++) {
    await page.evaluate(([s, k]) => window.showScene(s, k), [frames[i].scene, frames[i].step]);
    await page.waitForLoadState("networkidle");
    await page.screenshot({ path: path.join(dir, name(i)), clip: { x: 0, y: 0, width: size.width, height: size.height } });
  }
  await page.close();
}

function encode(listFile, wavFile, duration, outFile) {
  // Hum: three low sines, faded in and out, far under the voice.
  const hum = "aevalsrc='0.010*sin(2*PI*55*t)+0.006*sin(2*PI*110.3*t)+0.003*sin(2*PI*164.9*t)':s=48000:d=" + duration.toFixed(2);
  run(ffmpegPath(), ["-y", "-loglevel", "error",
    "-f", "concat", "-safe", "0", "-i", listFile,
    "-i", wavFile,
    "-f", "lavfi", "-i", hum,
    "-filter_complex",
    "[1:a]aresample=48000,aformat=channel_layouts=mono[v];" +
    "[2:a]afade=t=in:d=2,afade=t=out:st=" + Math.max(0, duration - 2.5).toFixed(2) + ":d=2.5[h];" +
    "[v][h]amix=inputs=2:normalize=0,aformat=channel_layouts=stereo[a];" +
    "[0:v]fps=" + FPS + ",format=yuv420p[vid]",
    "-map", "[vid]", "-map", "[a]",
    "-c:v", "libx264", "-preset", "medium", "-tune", "stillimage", "-crf", "20",
    "-c:a", "aac", "-b:a", "160k", "-t", duration.toFixed(2), "-movflags", "+faststart", outFile]);
}

function readTiming(file) {
  if (!fs.existsSync(file)) throw new Error("missing " + path.basename(file) + " (run voice.mjs first)");
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

async function main() {
  if (!/^\d{4}-W\d{2}$/.test(week)) { console.error("usage: video.mjs 2026-W47 [--only wide|tall|thumb]"); process.exit(1); }
  const data = JSON.parse(fs.readFileSync(path.join(RECAP, "data", week + ".json"), "utf8"));
  if (!data.narration || !data.narration.paragraphs || !data.short || !data.meta) throw new Error(week + ".json is from before stage 3: run week.js " + week + " --renarrate");
  const base = fileBase(week);
  const { chromium } = await import("playwright");
  const srv = await serve();
  const url = "http://127.0.0.1:" + srv.address().port;
  const browser = await chromium.launch(process.env.RECAP_BROWSER ? { channel: process.env.RECAP_BROWSER } : {});
  try {
    if (!only || only === "wide") {
      const timing = readTiming(path.join(OUT, week + ".timing.json"));
      if (timing.paragraphs.length !== data.narration.paragraphs.length) throw new Error("voice timing does not match the narration (run voice.mjs again)");
      const frames = frameTimes(timing);
      const dir = path.join(OUT, "frames-wide");
      await cards(browser, url, "wide", { width: 1920, height: 1080 }, frames, dir);
      fs.writeFileSync(path.join(dir, "list.txt"), concatList(frames, dir));
      encode(path.join(dir, "list.txt"), path.join(OUT, week + ".wav"), timing.duration, path.join(OUT, base + ".mp4"));
      console.log(base + ".mp4: " + timing.duration.toFixed(1) + " s, " + frames.length + " cards");
    }
    if (!only || only === "tall") {
      const timing = readTiming(path.join(OUT, week + "-short.timing.json"));
      if (timing.duration > SHORT_MAX_SECONDS) throw new Error("vertical cut is " + timing.duration.toFixed(1) + " s, over " + SHORT_MAX_SECONDS);
      const frames = frameTimes(timing);
      const dir = path.join(OUT, "frames-tall");
      await cards(browser, url, "tall", { width: 1080, height: 1920 }, frames, dir);
      fs.writeFileSync(path.join(dir, "list.txt"), concatList(frames, dir));
      encode(path.join(dir, "list.txt"), path.join(OUT, week + "-short.wav"), timing.duration, path.join(OUT, base + "-SHORT.mp4"));
      console.log(base + "-SHORT.mp4: " + timing.duration.toFixed(1) + " s");
    }
    if (!only || only === "thumb") {
      const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
      await page.goto(url + "/recap/render/?week=" + week + "&fmt=thumb", { waitUntil: "load" });
      await page.waitForFunction(() => window.recapReady || window.recapError, null, { timeout: 30000 });
      await page.waitForLoadState("networkidle");
      await page.screenshot({ path: path.join(OUT, base + "-THUMB.png") });
      await page.close();
      const m = data.meta;
      fs.writeFileSync(path.join(OUT, base + "-YOUTUBE.txt"),
        "TITLE\n" + m.title + "\n\nSHORT TITLE\n" + m.shortTitle + "\n\nDESCRIPTION\n" + m.description + "\n\nTAGS\n" + m.tags.join(", ") + "\n");
      console.log(base + "-THUMB.png, " + base + "-YOUTUBE.txt");
    }
  } finally {
    await browser.close();
    srv.close();
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) main().catch((e) => { console.error("STOP: " + e.message); process.exit(2); });
